<template><view class="page"><view class="header"><text>路跑线路</text><text>日常里程，折算为一场文化远征</text></view><view class="route" v-for="(r,i) in routes" :key="r.id" @tap="detail(r.id)"><view class="head"><image :src="r.scene" mode="aspectFill"/><view class="mask"/><view class="left"><text>{{r.name}}</text><text>{{r.from}} 至 {{r.to}}</text></view><view class="right"><text>{{r.spirit}}</text><text v-if="i===0" class="current">当前计入</text></view></view><view class="body"><view class="progress"><view :style="{width:r.pct+'%',background:r.theme}"/></view><view class="foot"><text>已跑 {{r.distance}} / {{r.total}} km · 抵达 {{r.current}}</text><text class="orange">{{r.pct}}%</text></view><text class="medal">完赛勋章：{{r.medalName}}</text></view></view></view></template>
<script>import {routes} from '../../common/mock.js';export default{data:()=>({routes}),methods:{detail(id){uni.navigateTo({url:'/pages/route/route?id='+id})}}}</script>
<style scoped>.page{padding-bottom:40rpx}.header{padding:40rpx 40rpx 10rpx}.header text{display:block;font-size:44rpx;font-weight:700}.header text+text{font-size:26rpx;color:#999;margin-top:8rpx;font-weight:400}.route{margin:24rpx;background:white;border-radius:20rpx;overflow:hidden;box-shadow:0 4rpx 16rpx rgba(0,0,0,.06)}.head{height:230rpx;position:relative}.head image,.mask{position:absolute;width:100%;height:100%}.mask{background:linear-gradient(180deg,rgba(0,0,0,.12),rgba(0,0,0,.6))}.left,.right{position:absolute;top:26rpx;color:white}.left{left:30rpx}.left text{display:block;font-size:44rpx;font-weight:700}.left text+text{font-size:24rpx;margin-top:8rpx;font-weight:400}.right{right:30rpx;display:flex;flex-direction:column;align-items:flex-end}.right>text:first-child{border:2rpx solid rgba(255,255,255,.85);border-radius:99rpx;padding:4rpx 18rpx}.current{color:#ff6a00;background:#fff;border-radius:8rpx;padding:3rpx 12rpx;margin-top:10rpx;font-size:20rpx}.body{padding:24rpx 30rpx}.progress{height:14rpx;background:#eee;border-radius:99rpx;overflow:hidden}.progress view{height:100%}.foot{display:flex;justify-content:space-between;color:#999;font-size:24rpx;margin-top:14rpx}.orange{color:#ff6a00}.medal{display:block;color:#f5a623;font-size:24rpx;margin-top:14rpx}</style>
